#!/usr/bin/env bash
# Copy the presentable, small outputs of an HRIBO run into the repository.
#
# A full HRIBO run leaves tens of gigabytes behind. What belongs under version
# control is the part a reader needs to judge the analysis: the summary
# tables, the quality control reports, the metagene plots, the ORF prediction
# tables, the logs, and a manifest with the size and md5 sum of every file.
# Coverage tracks (BigWig) and alignments are listed in the manifest but not
# copied; they are regenerated by the scripts.
#
# Usage:
#   WORK_DIR=/path/to/work bash scripts/06_collect_results.sh [results_name]
#
# Variables, all optional:
#   WORK_DIR      analysis directory (default: <repository>/work)
#   MAX_FILE_MB   files larger than this are listed but not copied (default: 25)

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WORK_DIR="${WORK_DIR:-${REPO_ROOT}/work}"
NAME="${1:-pao1}"
MAX_FILE_MB="${MAX_FILE_MB:-25}"
OUT="${REPO_ROOT}/results/${NAME}"

log() { printf '[%s] %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$*"; }
die() { printf '[error] %s\n' "$*" >&2; exit 1; }

[[ -d "$WORK_DIR" ]] || die "analysis directory not found: ${WORK_DIR}"
cd "$WORK_DIR"
mkdir -p "$OUT"

MANIFEST="${OUT}/manifest.tsv"
printf 'path\tbytes\tmd5\tcopied\n' > "$MANIFEST"

# copy_tree <source dir> [find expression...]
# Copies matching files below the source directory, keeping the relative
# path, and records every file whether copied or not.
copy_tree() {
  local src="$1"; shift
  [[ -d "$src" ]] || { log "skip (absent): ${src}"; return; }
  local f rel bytes md5 copied
  while IFS= read -r -d '' f; do
    rel="${f#./}"
    bytes="$(stat -c %s "$f")"
    md5="$(md5sum "$f" | cut -d' ' -f1)"
    if (( bytes <= MAX_FILE_MB * 1024 * 1024 )); then
      mkdir -p "${OUT}/$(dirname "$rel")"
      cp -p "$f" "${OUT}/${rel}"
      copied=yes
    else
      copied="no (larger than ${MAX_FILE_MB} MB)"
    fi
    printf '%s\t%s\t%s\t%s\n' "$rel" "$bytes" "$md5" "$copied" >> "$MANIFEST"
  done < <(find "./${src}" -type f "$@" -print0 | sort -z)
}

# list_tree <source dir> [find expression...]
# Records files without copying them (alignments, coverage tracks).
list_tree() {
  local src="$1"; shift
  [[ -d "$src" ]] || return 0
  local f
  while IFS= read -r -d '' f; do
    printf '%s\t%s\t%s\t%s\n' "${f#./}" "$(stat -c %s "$f")" "$(md5sum "$f" | cut -d' ' -f1)" "no (not collected)" >> "$MANIFEST"
  done < <(find "./${src}" -type f "$@" -print0 | sort -z)
}

log "collecting into ${OUT}"

# The summaries a reader opens first.
copy_tree auxiliary
copy_tree figures
copy_tree readcounts
copy_tree tracks -name 'potential*.gff' -o -name '*annotated*.gff' -o -name '*merged*.gff' -o -name 'totalAnnotation.gff'

# Quality control: the MultiQC report and the per-sample FastQC summaries.
copy_tree qc/multi -name 'multiqc_report.html'
copy_tree qc/multi/multiqc_data -name '*.txt'
copy_tree qc -name '*_fastqc.html'
copy_tree metageneprofiling

# ORF callers: the prediction tables and their diagnostic plots.
copy_tree reparation -name 'Predicted_ORFs.txt' -o -name '*.pdf' -o -name '*.png'
copy_tree deepribo -maxdepth 2 -name 'predictions.csv' -o -name 'parameters.txt'

# Differential expression, only present for multi-condition designs.
copy_tree contrasts
copy_tree xtail
copy_tree riborex
copy_tree deltate
copy_tree pca

# Logs: HRIBO's per-rule logs, snakemake's own log, and the logs of these scripts.
copy_tree logs
mkdir -p "${OUT}/logs/snakemake"
if compgen -G ".snakemake/log/*.log" > /dev/null; then
  for f in .snakemake/log/*.log; do
    cp -p "$f" "${OUT}/logs/snakemake/"
    printf '%s\t%s\t%s\tyes\n' "$f" "$(stat -c %s "$f")" "$(md5sum "$f" | cut -d' ' -f1)" >> "$MANIFEST"
  done
fi

# The configuration and sample sheet that were actually used.
mkdir -p "${OUT}/config_used"
cp -p HRIBO/config.yaml HRIBO/samples.tsv "${OUT}/config_used/"
[[ -f HRIBO/VERSION_INSTALLED ]] && cp -p HRIBO/VERSION_INSTALLED "${OUT}/config_used/HRIBO_VERSION"

# Large outputs are recorded, not copied.
list_tree bam
list_tree maplink
list_tree globaltracks
list_tree fiveprimetracks
list_tree threeprimetracks
list_tree centeredtracks

# Sizes of the whole analysis directory, for the resource section of the README.
{
  printf 'path\tsize\n'
  du -sh . .snakemake/conda .snakemake/singularity .conda_pkgs .envs fastq sra deepribo reparation 2>/dev/null \
    | awk -F'\t' '{ printf "%s\t%s\n", $2, $1 }'
  printf 'files_in_deepribo\t%s\n' "$(find deepribo -type f 2>/dev/null | wc -l)"
} > "${OUT}/logs/disk_usage.tsv"

log "manifest: $(($(wc -l < "$MANIFEST") - 1)) entries, $(grep -c $'\tyes$' "$MANIFEST") files copied"
log "done"
